  }
};

// Supported JSON values:
// String  -> "Jeet"
// Number  -> 22
// Boolean -> true
// Null    -> null
// Array   -> ["JavaScript", "React"]
// Object  -> { "city": "Kolkata" }

const user = {
  name: "Jeet",
  greet: function () {
    console.log("Hello");
  }
};

const json = JSON.stringify(user);

console.log(json);
// '{"name":"Jeet"}'

// The greet function is removed.

const original = {
  name: "Jeet",
  date: new Date(),
  value: undefined,
  greet: () => console.log("Hello"),
  numbers: new Set([1, 2, 3])
};

const clone = JSON.parse(JSON.stringify(original));

console.log(clone);

// Problems:
// undefined -> removed
// function  -> removed
// Date      -> converted to a string
// Set       -> not preserved as a Set
// Circular references -> JSON.stringify() throws an error
// BigInt    -> JSON.stringify() throws an error
